t.script:
(function () {
    var dataEl = document.getElementById("education_data");
    if (!dataEl) return;
    var eduData = JSON.parse(dataEl.textContent);
    var select = document.getElementById("edu_level_select");
    if (!select) return;

    function updateFields() {
        var rec = eduData[select.value];
        if (!rec) return;
        document.getElementById("edu_level_hidden").value = rec.level_id;
        document.getElementById("edu_level_hidden2").value = rec.level_id;
        document.getElementById("edu_program_display").value = rec.program;
        document.getElementById("edu_program_hidden").value = rec.program;
        document.getElementById("edu_major_display").value = rec.major;
        document.getElementById("edu_major_hidden").value = rec.major;
        document.getElementById("edu_institution_display").value = rec.institution;
        document.getElementById("edu_institution_hidden").value = rec.institution;
        document.getElementById("edu_graduation_date_display").value = rec.graduation_date;
        document.getElementById("edu_graduation_date_hidden").value = rec.graduation_date;
        document.getElementById("edu_country_id_hidden").value = rec.country_id;
    }

    select.addEventListener("change", updateFields);
})();
